CREATE TABLE IF NOT EXISTS web_push_subscriptions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL, user_agent TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, last_success_at TEXT);
CREATE INDEX IF NOT EXISTS web_push_subscriptions_user ON web_push_subscriptions(user_id, created_at);
CREATE INDEX IF NOT EXISTS web_push_subscriptions_session ON web_push_subscriptions(session_id);
CREATE TABLE IF NOT EXISTS web_push_deliveries (run_id TEXT NOT NULL REFERENCES watch_runs(id) ON DELETE CASCADE, device_id TEXT NOT NULL REFERENCES web_push_subscriptions(id) ON DELETE CASCADE, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, expires_at TEXT NOT NULL, updated_at TEXT NOT NULL, reason TEXT, PRIMARY KEY(run_id, device_id));
CREATE INDEX IF NOT EXISTS web_push_deliveries_due ON web_push_deliveries(status, next_attempt_at);
